import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import Button from '../../components/common/Button/Button';
import Input from '../../components/common/Input/Input';
import PasswordInput from '../../components/common/PasswordInput/PasswordInput';
import ToggleButton from '../../components/common/ToggleButton/ToggleButton';
import styles from './RegisterPage.module.css';

const RegisterPage = () => {
    const navigate = useNavigate();
    const { register } = useAuth();
    const [formData, setFormData] = useState({ name: '', email: '', phone: '', gameLevel: 'D2', password: '', confirmPassword: '' });
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const levels = ['D1', 'D2', 'D3', 'D4', 'D4Plus'];

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (formData.password !== formData.confirmPassword) {
            setError('Пароли не совпадают');
            return;
        }
        setError('');
        setLoading(true);
        try {
            await register(formData);
            navigate('/');
        } catch (err) {
            setError(err.message || 'Ошибка регистрации');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className={styles.registerPage}>
            <div className={styles.container}>
                <div className={styles.registerCard}>
                    <div className={styles.header}>
                        <div className={styles.logo}>🏐</div>
                        <h1 className={styles.title}>Регистрация</h1>
                        <p className={styles.subtitle}>Создайте новый аккаунт</p>
                    </div>
                    <form onSubmit={handleSubmit} className={styles.form}>
                        {error && <div className={styles.errorMessage}>{error}</div>}
                        <Input label="Имя" placeholder="Введите ваше имя" value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} required />
                        <Input label="Email" type="email" placeholder="Введите ваш email" value={formData.email} onChange={(e) => setFormData({...formData, email: e.target.value})} required />
                        <Input label="Телефон" placeholder="+375 29 123-45-67" value={formData.phone} onChange={(e) => setFormData({...formData, phone: e.target.value})} />
                        <div className={styles.levelSection}>
                            <label className={styles.label}>Уровень игры *</label>
                            <div className={styles.levelButtons}>
                                {levels.map(level => (<ToggleButton key={level} label={level === 'D4Plus' ? 'D4+' : level} isActive={formData.gameLevel === level} onClick={() => setFormData({...formData, gameLevel: level})} />))}
                            </div>
                        </div>
                        <PasswordInput label="Пароль" placeholder="Введите пароль" value={formData.password} onChange={(e) => setFormData({...formData, password: e.target.value})} />
                        <PasswordInput label="Подтверждение пароля" placeholder="Подтвердите пароль" value={formData.confirmPassword} onChange={(e) => setFormData({...formData, confirmPassword: e.target.value})} />
                        <Button type="submit" fullWidth size="large" loading={loading}>Зарегистрироваться</Button>
                    </form>
                    <div className={styles.footer}>
                        <p className={styles.loginLink}>Уже есть аккаунт? <a href="/login">Войти</a></p>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default RegisterPage;
